import sys

def main():
    data = sys.stdin.read().split()
    m, n, B = int(data[0]), int(data[1]), int(data[2])
    bread = [int(x) for x in data[3:3 + m]]
    sauce = [int(x) for x in data[3 + m:3 + m + n]]
    cap = max(2 * B, min(bread))
    mask = (1 << (cap + 1)) - 1
    reach = [0] * (n + 1)
    reach[n] = 1
    for i in range(n - 1, -1, -1):
        reach[i] = (reach[i + 1] | (reach[i + 1] << sauce[i])) & mask
    chosen = None
    for d in range(0, cap + B + 2):
        for t in (B - d, B + d):
            if t < 1 or t > cap:
                continue
            for bi in range(m):
                if bread[bi] <= t and (reach[0] >> (t - bread[bi])) & 1:
                    chosen = (t, bi)
                    break
            if chosen:
                break
            if d == 0:
                break
        if chosen:
            break
    t, bi = chosen
    r = t - bread[bi]
    picks = []
    i = 0
    while r > 0:
        for j in range(i, n):
            if sauce[j] <= r and (reach[j + 1] >> (r - sauce[j])) & 1:
                picks.append(j)
                r -= sauce[j]
                i = j + 1
                break
    print(t)
    print(bi)
    print(' '.join(map(str, [len(picks)] + picks)))

